 106|// evaluateConstraintGate runs constraint evaluation with backoff, retry counting,
 107|// early termination, and context cleanup. Returns (blocked, error) where blocked
 108|// is true if the task should not transition (constraints failed or backoff active).
 109|func (o *Orchestrator) evaluateConstraintGate(task *model.Task) (bool, error) {
 110|	if task.Context == nil {
 111|		task.Context = make(model.JSONField)
 112|	}
 113|
 114|	policy := DefaultConstraintGatePolicy()
 115|
 116|	// Check backoff: if next_check is in the future, skip evaluation.
 117|	if nextCheckStr, ok := task.Context["constraint_gate_next_check"].(string); ok {
 118|		nextCheck, err := time.Parse(time.RFC3339, nextCheckStr)
 119|		if err == nil && time.Now().Before(nextCheck) {
 120|			return true, nil
 121|		}
 122|	}
 123|
 124|	fn := strings.TrimPrefix(task.WorktreeBranch, "feature/")
 125|	featureDir := o.worktree.FeatureWorktreePath(fn)
 126|
 127|	constraintCfg, cfgErr := constraints.LoadConfig(featureDir)
 128|	if cfgErr != nil {
 129|		o.logger.Warn("constraint config load failed at integration gate",
 130|			"task_id", task.ID, "error", cfgErr)
 131|		return false, nil
 132|	}
 133|	if constraintCfg == nil {
 134|		return false, nil
 135|	}
 136|
 137|	masterDir := ""
 138|	if md, err := o.worktree.MainWorktreePath(); err == nil {
 139|		masterDir = md
 140|	} else {
 141|		o.logger.Warn("master worktree not found for constraint delta",
 142|			"task_id", task.ID, "error", err)
 143|		o.emit("constraint_gate_skip", map[string]any{
 144|			"task_id": task.ID,
