 154|		return false, nil
 155|	}
 156|
 157|	if delta.Skipped {
 158|		o.logger.Warn("constraint gate skipped: baseline unavailable",
 159|			"task_id", task.ID,
 160|			"baseline_status", delta.BaselineStatus,
