  14|// processBacklog transitions a task from BACKLOG to PLANNING.
  15|// Quick fix tasks skip planning and go directly to IN_PROGRESS.
  16|// When replanning (PlanFeedback is set), it detaches old subtasks first
  17|// to prevent the planner from seeing stale done subtasks and auto-advancing.
  18|// When experiments are active, normal (non-experiment) tasks are blocked.
  19|func (o *Orchestrator) processBacklog(task *model.Task) error {
  20|	if task.Category.IsQuickFix() {
  21|		return o.processQuickFix(task)
  22|	}
  23|
  24|	// Experiment-aware scheduling: block normal tasks when experiments are active.
  25|	if o.experimentScheduler != nil {
  26|		canSchedule, reason, err := o.experimentScheduler.CanScheduleTask(task.ID)
  27|		if err != nil {
  28|			o.logger.Warn("experiment scheduler check failed", "task_id", task.ID, "error", err)
  29|		} else if !canSchedule {
  30|			o.logger.Debug("task blocked by experiment scheduler", "task_id", task.ID, "reason", reason)
  31|			return nil
  32|		}
  33|	}
  34|
  35|	if task.PlanFeedback != "" {
  36|		var oldSubtasks []model.Task
  37|		o.db.Where("parent_task_id = ?", task.ID).Find(&oldSubtasks)
  38|		if len(oldSubtasks) > 0 {
  39|			for i := range oldSubtasks {
  40|				oldSubtasks[i].ParentTaskID = nil
  41|				o.db.Save(&oldSubtasks[i])
  42|			}
  43|			slog.Info("detached old subtasks for replanning",
  44|				"task_id", task.ID, "count", len(oldSubtasks))
  45|		}
  46|	}
  47|
  48|	event, err := state.TransitionTask(task, model.StatusPlanning, "orchestrator", nil)
  49|	if err != nil {
  50|		return fmt.Errorf("process backlog: %w", err)
  51|	}
  52|	if err := o.db.Save(task).Error; err != nil {
  53|		return fmt.Errorf("process backlog: save task: %w", err)
  54|	}
  55|	if err := o.db.Create(event).Error; err != nil {
  56|		return fmt.Errorf("process backlog: save event: %w", err)
  57|	}
  58|	o.emit("task_updated", task)
  59|	o.publishTaskTransition(task.ID.String(), event.OldValue, event.NewValue, "")
  60|	o.logger.Info("task transitioned to planning", "task_id", task.ID, "title", task.Title)
  61|	return nil
  62|}
  63|
  64|// processPlanning handles tasks in the PLANNING state by either transitioning
  65|// them to PLAN_REVIEW (if a plan exists), monitoring an assigned planner agent,
  66|// or spawning a new planner.
  67|func (o *Orchestrator) processPlanning(task *model.Task) error {
  68|	// 0. If plan exists but PlanFeedback requests a re-plan, clear the stale
  69|	// plan so a new planner is spawned below. Without this, the same plan
  70|	// would be auto-advanced to PLAN_REVIEW without addressing the feedback.
  71|	if task.Plan != nil && task.PlanFeedback != "" {
  72|		o.logger.Info("clearing stale plan for replan with feedback",
  73|			"task_id", task.ID, "feedback", task.PlanFeedback)
  74|		task.Plan = nil
  75|		task.AssignedAgentID = nil
  76|		if err := o.db.Save(task).Error; err != nil {
  77|			return fmt.Errorf("process planning: save cleared plan: %w", err)
  78|		}
  79|	}
  80|
  81|	// 1. If plan already exists, evaluate for clarification needs.
  82|	if task.Plan != nil {
  83|		dec := o.decideClarification(task)
  84|		if dec.CapReached {
  85|			// Round cap hit — record it for observability then fall through to plan_review.
  86|			if task.Context == nil {
  87|				task.Context = make(model.JSONField)
  88|			}
  89|			task.Context["clarification_cap_reached"] = true
  90|			o.logger.Info("clarification round cap reached, skipping to plan_review",
  91|				"task_id", task.ID, "rounds", dec.Rounds)
  92|		} else if !dec.Proceed {
  93|			// Clarification needed — set context and transition.
  94|			if task.Context == nil {
  95|				task.Context = make(model.JSONField)
  96|			}
  97|			task.Context["clarification_session"] = dec.SessionData
  98|			task.Context["clarification_questions"] = dec.Questions
  99|			if len(dec.Questions) > 0 {
 100|				task.Context["clarification_current_question"] = dec.Questions[0]
 101|			}
 102|			task.Context["clarification_rounds"] = float64(dec.Rounds + 1)
 103|			event, transErr := state.TransitionTask(task, model.StatusNeedsClarification, "orchestrator", nil)
 104|			if transErr != nil {
 105|				return fmt.Errorf("process planning: transition to needs_clarification: %w", transErr)
 106|			}
 107|			if err := o.db.Save(task).Error; err != nil {
 108|				return fmt.Errorf("process planning: save task: %w", err)
 109|			}
 110|			if err := o.db.Create(event).Error; err != nil {
 111|				return fmt.Errorf("process planning: save event: %w", err)
 112|			}
 113|			o.emit("needs_clarification", map[string]any{"task_id": task.ID, "questions": dec.Questions})
 114|			o.publishTaskTransition(task.ID.String(), event.OldValue, event.NewValue, "needs clarification")
 115|			return nil
 116|		}
 117|
 118|		// No clarification needed (or cap reached) — proceed to plan_review.
 119|		event, err := state.TransitionTask(task, model.StatusPlanReview, "orchestrator", nil)
 120|		if err != nil {
 121|			return fmt.Errorf("process planning: transition to plan_review: %w", err)
 122|		}
 123|		if err := o.db.Save(task).Error; err != nil {
 124|			return fmt.Errorf("process planning: save task: %w", err)
 125|		}
 126|		if err := o.db.Create(event).Error; err != nil {
 127|			return fmt.Errorf("process planning: save event: %w", err)
 128|		}
 129|		o.emit("plan_ready", map[string]any{"task_id": task.ID})
 130|		o.publishTaskTransition(task.ID.String(), event.OldValue, event.NewValue, "plan ready for review")
 131|		return nil
 132|	}
 133|
 134|	// 2. If an agent is assigned, check if it's still running.
 135|	if task.AssignedAgentID != nil {
 136|		var ag model.Agent
 137|		if err := o.db.First(&ag, "id = ?", task.AssignedAgentID).Error; err != nil {
 138|			// Agent record missing — clear assignment.
 139|			o.logger.Warn("assigned planner agent not found, clearing", "task_id", task.ID, "agent_id", task.AssignedAgentID)
 140|			task.AssignedAgentID = nil
 141|			retries := o.incrementRetryCount(task)
 142|			if retries >= MaxPlannerRetries {
 143|				return o.failTask(task, "planner agent disappeared after max retries")
 144|			}
 145|			return o.db.Save(task).Error
 146|		}
 147|
 148|		// If agent is dead or idle (finished without plan), clean up its
 149|		// worktree, clear assignment, and maybe retry.
 150|		if ag.Status == model.AgentDead || ag.Status == model.AgentIdle {
 151|			if ag.WorktreeBranch != "" {
 152|				if err := o.worktree.RemoveAgentWorktree(ag.WorktreeBranch); err != nil {
 153|					o.logger.Warn("cleanup dead planner worktree failed", "agent_id", ag.ID, "error", err)
 154|				}
 155|			}
 156|			task.AssignedAgentID = nil
 157|			retries := o.incrementRetryCount(task)
 158|			if retries >= MaxPlannerRetries {
 159|				return o.failTask(task, "planner agent failed after max retries")
 160|			}
 161|			o.logger.Warn("planner agent dead/idle, will retry", "task_id", task.ID, "retries", retries)
 162|			return o.db.Save(task).Error
 163|		}
 164|
 165|		// Agent is still working — do nothing (recoverStuckAgents handles fallback).
 166|		return nil
 167|	}
 168|
 169|	// 3. No agent assigned — spawn a planner if capacity allows.
 170|
 171|	// Hard cap: prevent runaway planner spawns across all cycles.
 172|	totalSpawns := 0
 173|	if task.Context != nil {
 174|		if v, ok := task.Context["total_planner_spawns"].(float64); ok {
 175|			totalSpawns = int(v)
 176|		}
 177|	}
 178|	if totalSpawns >= MaxTotalPlannerSpawns {
 179|		return o.failTask(task, fmt.Sprintf(
 180|			"planner spawn cap reached (%d/%d) — task needs human review",
 181|			totalSpawns, MaxTotalPlannerSpawns))
 182|	}
 183|
 184|	if !o.runner.CanSpawn() {
 185|		return nil // wait for capacity
 186|	}
 187|
 188|	// Load project for prompt context.
 189|	var project model.Project
 190|	if err := o.db.First(&project, "id = ?", o.projectID).Error; err != nil {
 191|		return fmt.Errorf("process planning: load project: %w", err)
 192|	}
 193|
 194|	// Create feature worktree if needed.
 195|	if task.WorktreeBranch == "" {
 196|		featureName := taskFeatureName(task)
 197|		wtInfo, err := o.worktree.CreateFeature(featureName)
 198|		if err != nil {
 199|			return fmt.Errorf("process planning: create feature: %w", err)
 200|		}
