 114|	policy := DefaultConstraintGatePolicy()
 115|
 116|	// Check backoff: if next_check is in the future, skip evaluation.
 117|	if nextCheckStr, ok := task.Context["constraint_gate_next_check"].(string); ok {
 118|		nextCheck, err := time.Parse(time.RFC3339, nextCheckStr)
 119|		if err == nil && time.Now().Before(nextCheck) {
 120|			return true, nil
 121|		}
 122|	}
 123|
 124|	fn := strings.TrimPrefix(task.WorktreeBranch, "feature/")
 125|	featureDir := o.worktree.FeatureWorktreePath(fn)
 126|
 127|	constraintCfg, cfgErr := constraints.LoadConfig(featureDir)
 128|	if cfgErr != nil {
 129|		o.logger.Warn("constraint config load failed at integration gate",
 130|			"task_id", task.ID, "error", cfgErr)
 131|		return false, nil
